all.example:
for (const pot of kcds.world.CookPot.all()) {
  console.info(pot.guid, pot.food, pot.portions);
}

get.example:
const { CookPot } = kcds.world;

const pot = CookPot.get(guid);
if (pot && pot.portions === 0) {
  CookPot.refill(guid);
}

get.exampleCs:
var pot = CookPot.Get(guid);
if (pot && pot["portions"].AsNumber() == 0)
{
    CookPot.Refill(guid);
}

refill.example:
const { CookPot } = kcds.world;

for (const pot of CookPot.all()) {
  CookPot.refill(pot.guid, 6);
}

setFire.example:
const { CookPot } = kcds.world;

const [tavernPot] = CookPot.all();
if (tavernPot) {
  CookPot.setFire(tavernPot.guid, true);
}

setFire.exampleCs:
var tavernPot = CookPot.All()[0];
if (tavernPot)
{
    CookPot.SetFire(tavernPot["guid"], true);
}

topUpFrom.example:
const answer = kcds.world.CookPot.topUpFrom(player, guid, {
  food: 'goulash',
  portions: 4,
  ingredients: [{ item: 'boarMeat', amount: 1 }, { item: 'onion', amount: 2 }],
});
if (!answer.ok) {
  kcds.core.Chat.sendToPlayer(player, `You cannot cook: ${answer.code}`);
}

topUpFrom.exampleCs:
var answer = CookPot.TopUpFrom(player, guid, new { food = "goulash", portions = 4, ingredients = new object[] { new { item = "boarMeat", amount = 1 }, new { item = "onion", amount = 2 } } });
if (!answer["ok"])
{
    Chat.SendToPlayer(player, $"You cannot cook: {answer["code"]}");
}
